namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private int _nextId;
    // category -> recipe id -> list of ratings
    private readonly Dictionary<int, List<int>> _ratings = new();

    public RecipeService()
    {
        _recipes =
        [
            new Recipe
            {
                Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
                Description = "A simple yet delicious pizza with fresh mozzarella and basil.",
                Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
                Steps = [
                    "Preheat oven to 475°F (245°C) with a pizza stone if available.",
                    "Stretch dough into a 12-inch round on a floured surface.",
                    "Spread crushed tomatoes evenly, leaving a 1-inch border.",
                    "Tear mozzarella into pieces and distribute over the sauce.",
                    "Bake for 10–12 minutes until crust is golden and cheese is bubbly.",
                    "Top with fresh basil leaves and a drizzle of olive oil."
                ],
                AverageRating = 4.5, RatingCount = 12
            },
            new Recipe
            {
                Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
                Description = "Creamy Roman pasta with eggs, cheese, and pancetta.",
                Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
                Steps = [
                    "Cook spaghetti in salted boiling water until al dente.",
                    "Crisp pancetta in a skillet over medium heat.",
                    "Whisk eggs with grated Pecorino and pepper in a bowl.",
                    "Drain pasta, reserving 1 cup pasta water.",
                    "Toss hot pasta with pancetta, then remove from heat.",
                    "Pour egg mixture over pasta and toss quickly, adding pasta water as needed."
                ],
                AverageRating = 4.8, RatingCount = 20
            },
            new Recipe
            {
                Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
                Description = "Tender chicken pieces in a rich, spiced tomato-cream sauce.",
                Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato puree", "Heavy cream", "Onion", "Garlic", "Ginger"],
                Steps = [
                    "Marinate chicken in yogurt and spices for at least 1 hour.",
                    "Grill or broil chicken until lightly charred.",
                    "Sauté onion, garlic, and ginger in a large pan.",
                    "Add tomato puree and simmer for 15 minutes.",
                    "Stir in cream and garam masala.",
                    "Add chicken pieces and simmer for 10 more minutes."
                ],
                AverageRating = 4.6, RatingCount = 15
            },
            new Recipe
            {
                Id = 4, Title = "Vegetable Pad Thai", Category = "Asian",
                Description = "A vibrant stir-fried noodle dish with a tangy tamarind sauce.",
                Ingredients = ["Rice noodles", "Tofu", "Bean sprouts", "Peanuts", "Tamarind paste", "Fish sauce", "Lime", "Green onions"],
                Steps = [
                    "Soak rice noodles in warm water for 20 minutes, then drain.",
                    "Press and cube tofu, then pan-fry until golden.",
                    "Mix tamarind paste, fish sauce, and sugar for the sauce.",
                    "Stir-fry noodles with sauce on high heat for 2 minutes.",
                    "Add tofu, bean sprouts, and green onions.",
                    "Serve with crushed peanuts and lime wedges."
                ],
                AverageRating = 4.3, RatingCount = 9
            },
            new Recipe
            {
                Id = 5, Title = "Beef Tacos", Category = "Mexican",
                Description = "Seasoned ground beef in crispy tortillas with fresh toppings.",
                Ingredients = ["Ground beef", "Taco seasoning", "Corn tortillas", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Salsa"],
                Steps = [
                    "Brown ground beef in a skillet over medium-high heat.",
                    "Add taco seasoning and water, simmer for 5 minutes.",
                    "Warm tortillas in a dry skillet or oven.",
                    "Fill tortillas with seasoned beef.",
                    "Top with shredded lettuce, diced tomato, cheese, sour cream, and salsa."
                ],
                AverageRating = 4.2, RatingCount = 18
            },
            new Recipe
            {
                Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts",
                Description = "Rich individual cakes with a molten chocolate center.",
                Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
                Steps = [
                    "Preheat oven to 425°F (220°C). Butter and flour ramekins.",
                    "Melt chocolate and butter together, then let cool slightly.",
                    "Whisk eggs, sugar, and vanilla until thick.",
                    "Fold chocolate mixture into eggs, then gently fold in flour.",
                    "Pour into ramekins and bake for 12–14 minutes.",
                    "Let rest 1 minute, then invert onto plates and serve immediately."
                ],
                AverageRating = 4.9, RatingCount = 25
            }
        ];
        _nextId = 7;
    }

    public IReadOnlyList<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().Order().ToList();
    }

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipe(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetRecipe(recipeId);
        if (recipe is null || stars < 1 || stars > 5) return;

        if (!_ratings.TryGetValue(recipeId, out var ratings))
        {
            ratings = [];
            _ratings[recipeId] = ratings;
        }

        ratings.Add(stars);
        recipe.RatingCount = ratings.Count;
        recipe.AverageRating = ratings.Average();
    }

    public Recipe AddRecipe(RecipeSubmission submission)
    {
        var recipe = new Recipe
        {
            Id = _nextId++,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList(),
            Steps = submission.Steps
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .ToList()
        };
        _recipes.Add(recipe);
        return recipe;
    }
}

